choose.when:
SELECT CAST(JSON_OBJECT(
    'displayName', a.display_name, 'version', a.version,
    'openAlexId', (SELECT e.external_id FROM author_external_id e WHERE e.author_id = a.id AND e.id_type = 'OPENALEX'),
    'orcid', (SELECT e.external_id FROM author_external_id e WHERE e.author_id = a.id AND e.id_type = 'ORCID'),
    'achievementCount', (SELECT COUNT(*) FROM achievement_author au WHERE au.author_id = a.id)
) AS CHAR CHARACTER SET utf8mb4) FROM author a WHERE a.id = #{entityId}

SELECT CAST(JSON_OBJECT(
    'displayName', o.display_name, 'version', o.version, 'type', o.organization_type,
    'openAlexId', o.openalex_id, 'countryCode', o.country_code,
    'ror', (SELECT e.external_id FROM organization_external_id e WHERE e.organization_id = o.id AND e.id_type = 'ROR')
) AS CHAR CHARACTER SET utf8mb4) FROM organization o WHERE o.id = #{entityId}

SELECT CAST(JSON_OBJECT(
    'displayName', v.display_name, 'version', v.version, 'type', v.venue_type,
    'openAlexId', v.openalex_id, 'issnL', v.issn_l
) AS CHAR CHARACTER SET utf8mb4) FROM venue v WHERE v.id = #{entityId}

mapper.update:
UPDATE duplicate_candidate
SET status = #{status}, version = version + 1, updated_at = UTC_TIMESTAMP(6)
WHERE id = #{candidateId} AND version = #{expectedVersion}

mapper.insert:
INSERT INTO data_revision (
    entity_type, entity_id, revision_action, before_json, after_json,
    actor_user_id, reason, reversible, created_at
) VALUES (
    #{entityType}, #{entityId}, #{action}, #{beforeJson}, #{afterJson},
    #{actorUserId}, #{reason}, #{reversible}, #{createdAt}
)

INSERT INTO canonical_entity_link (
    entity_type, entity_id, canonical_entity_id, revision_id
) VALUES (#{entityType}, #{entityId}, #{canonicalEntityId}, #{revisionId})

INSERT INTO merge_decision (
    candidate_id, decision, canonical_entity_id, revision_id,
    actor_user_id, reason, decided_at
) VALUES (
    #{candidateId}, #{decision}, #{canonicalEntityId}, #{revisionId},
    #{actorUserId}, #{reason}, #{decidedAt}
)

mapper.select:
SELECT id, candidate_id, decision, canonical_entity_id, revision_id,
       actor_user_id, reason, version, decided_at
FROM merge_decision WHERE id = #{decisionId}

SELECT COUNT(*) FROM canonical_entity_link
WHERE entity_type = #{entityType}
  AND entity_id = #{canonicalEntityId}
  AND revision_id != #{revisionId}

