INSERT INTO manual_field_override (
    achievement_id, field_name, field_value, revision_id,
    actor_user_id, reason, active, version, created_at, updated_at
) VALUES (
    #{achievementId}, #{fieldName}, #{fieldValue}, #{revisionId},
